(function(){
  const U='https://bpnkouymdvcogeaqjmxl.supabase.co';
  const K='sb_publishable_v6rJbF4IfGZTKtbuQtmsmQ_lS3sXWFa';
  const $=id=>document.getElementById(id);
  let cats=[];
  function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function token(){try{const x=JSON.parse(localStorage.getItem('sb-bpnkouymdvcogeaqjmxl-auth-token')||'null');return x?.access_token||''}catch{return''}}
  async function api(body){const t=token();if(!t)throw Error('Please sign in again.');const r=await fetch(U+'/functions/v1/collection-orders-api',{method:'POST',headers:{apikey:K,Authorization:'Bearer '+t,'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(d.error||'Request failed'),{status:r.status});return d}
  function addCard(){const page=$('staffPage');if(!page||$('staffStockControlCard'))return;const card=document.createElement('div');card.className='card hidden';card.id='staffStockControlCard';card.innerHTML='<h2>📦 Stock Control</h2><p class="muted">Mark menu items out of stock so customers cannot order them for collection.</p><input id="staffStockSearch" class="input" placeholder="Search items"><div id="staffStockList"><p class="muted">Loading stock…</p></div>';
    page.appendChild(card);$('staffStockSearch').addEventListener('input',render);load();}
  async function load(){const card=$('staffStockControlCard');if(!card)return;try{const d=await api({action:'stock_list'});cats=d.categories||[];card.classList.remove('hidden');render()}catch(e){if(e.status===403)card.classList.add('hidden');else $('staffStockList').innerHTML='<p class="muted">'+esc(e.message)+'</p>'}}
  function render(){const root=$('staffStockList'),search=$('staffStockSearch');if(!root)return;const q=(search?.value||'').trim().toLowerCase();const open=new Set(Array.from(root.querySelectorAll('.staff-stock-cat[open]')).map(x=>x.dataset.cat));let h='';for(const c of cats){const key=String(c.id||c.name),items=(c.loyalty_menu_items||[]).filter(i=>!q||(`${c.name} ${i.name}`).toLowerCase().includes(q));if(!items.length)continue;h+=`<details class="staff-stock-cat" data-cat="${esc(key)}" ${q||open.has(key)?'open':''}><summary><span>${esc(c.name)} <small>(${items.length})</small></span><span class="staff-stock-arrow">▾</span></summary><div class="staff-stock-body">${items.map(i=>`<div class="staff-stock-row"><span>${esc(i.name)}</span><button type="button" class="staff-stock-btn ${i.in_stock?'in':'out'}" data-id="${esc(i.id)}" data-value="${i.in_stock?'1':'0'}">${i.in_stock?'IN STOCK':'OUT OF STOCK'}</button></div>`).join('')}</div></details>`}root.innerHTML=h||'<p class="muted">No items found.</p>';root.querySelectorAll('[data-id]').forEach(b=>b.onclick=async e=>{e.preventDefault();e.stopPropagation();const parent=b.closest('.staff-stock-cat');const keep=parent?.dataset.cat||'';b.disabled=true;try{await api({action:'set_stock',id:b.dataset.id,in_stock:b.dataset.value!=='1'});await load();const same=Array.from(root.querySelectorAll('.staff-stock-cat')).find(x=>x.dataset.cat===keep);if(same)same.open=true}catch(err){alert(err.message)}finally{b.disabled=false}})}
  const style=document.createElement('style');style.id='staffStockControlStyle';style.textContent='#staffStockControlCard .staff-stock-cat{background:#0d1829;border:1px solid #2b4161;border-radius:14px;margin:10px 0;overflow:hidden}#staffStockControlCard .staff-stock-cat summary{list-style:none;cursor:pointer;padding:13px;display:flex;justify-content:space-between;align-items:center;font-weight:900}#staffStockControlCard .staff-stock-cat summary::-webkit-details-marker{display:none}#staffStockControlCard .staff-stock-cat[open] .staff-stock-arrow{transform:rotate(180deg)}#staffStockControlCard .staff-stock-arrow{color:#ffd43b;font-size:19px}#staffStockControlCard .staff-stock-body{padding:0 13px}#staffStockControlCard .staff-stock-row{display:flex;gap:10px;align-items:center;padding:11px 0;border-top:1px solid #ffffff18}#staffStockControlCard .staff-stock-row>span{flex:1;font-weight:800}#staffStockControlCard .staff-stock-btn{border:0;border-radius:10px;padding:9px 10px;font-weight:900}.staff-stock-btn.in{background:#166534;color:#dcfce7}.staff-stock-btn.out{background:#991b1b;color:#fee2e2}';document.head.appendChild(style);
  addCard();const authView=$('appView');if(authView)new MutationObserver(()=>{if(!authView.classList.contains('hidden')&&token())load();else $('staffStockControlCard')?.classList.add('hidden')}).observe(authView,{attributes:true,attributeFilter:['class']});setTimeout(addCard,500);setTimeout(addCard,1500);document.addEventListener('visibilitychange',()=>{if(!document.hidden){addCard();if($('staffStockControlCard')&&!$('staffStockControlCard').classList.contains('hidden'))load()}});setInterval(()=>{if(!document.hidden&&$('staffStockControlCard')&&!$('staffStockControlCard').classList.contains('hidden'))load()},15000);
})();

(function(root){
  'use strict';
  const uuid='[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
  function parse(raw){
    const value=String(raw||'').trim();
    if(/^(?:DEXTERS:)?\d{6}$/.test(value))return {kind:'customer',id:value.slice(-6),raw:'DEXTERS:'+value.slice(-6)};
    const match=value.match(new RegExp('^DEXTERS(?:_|-)(DEAL|SPIN|POINTS|OFFER|COFFEE):('+uuid+')$','i'));
    if(!match)throw new Error('Not a valid Dexter’s QR. Enter the customer’s 6-digit code or the full reward code.');
    return {kind:match[1].toLowerCase(),id:match[2].toLowerCase(),raw:'DEXTERS_'+match[1].toUpperCase()+':'+match[2].toLowerCase()};
  }
  function spend(value){
    const s=String(value).trim();
    if(!/^\d{1,5}(\.\d{1,2})?$/.test(s))throw new Error('Enter a valid amount with no more than two decimal places.');
    const [whole,fraction='']=s.split('.'),pence=Number(whole)*100+Number(fraction.padEnd(2,'0'));
    if(pence<100||pence>1000000)throw new Error('Enter an order value between £1 and £10,000.');
    return {pence,points:Math.floor(pence/100),value:(pence/100).toFixed(2)};
  }
  function requestId(){
    if(typeof crypto.randomUUID==='function')return crypto.randomUUID();
    const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;
    const h=Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');
    return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20);
  }
  class Scanner {
    constructor(api){this.api=api;this.current=null;this.busy=false;this.generation=0;this.request=null;}
    cancel(){this.generation++;this.current=null;this.request=null;}
    async scan(raw){
      if(this.busy)throw new Error('Wait for the current action to finish.');
      this.cancel();const generation=this.generation,code=parse(raw);
      const result=await this.api('lookup',{raw:code.raw});
      if(generation!==this.generation)return null;
      this.current={...result,raw:code.raw};return this.current;
    }
    async act(action,amount){
      if(this.busy)throw new Error('Please wait — checking the result.');
      if(!this.current)throw new Error('Scan or enter a code first.');
      const raw=this.current.raw;
      if(action==='redeem'&&(this.current.kind==='customer'||this.current.status!=='valid'))throw new Error('This QR cannot be redeemed.');
      if(action!=='redeem'&&this.current.kind!=='customer')throw new Error('Scan the customer loyalty QR to add stamps or points.');
      const value=action==='points'?spend(amount).value:null;
      const signature=JSON.stringify([action,raw,value]);
      // Preserve the same request ID on retries after an uncertain network result.
      if(this.request&&this.request.signature!==signature)throw new Error('Retry the previous action first, or check the customer balance before scanning again.');
      if(!this.request)this.request={signature,id:requestId()};
      this.busy=true;
      try{const result=await this.api(action,{raw,amount:value,request_id:this.request.id});this.request=null;this.cancel();return result;}
      finally{this.busy=false;}
    }
  }
  const api={parse,spend,requestId,Scanner};if(typeof module!=='undefined')module.exports=api;else root.DextersQR=api;
})(typeof window==='undefined'?{}:window);
